fast_pseudocode:
# CORRECT: grid must be a lambda that reads meta['XBLOCK'] and meta['YBLOCK']
@triton.autotune(configs=[Config({'XBLOCK':64,'YBLOCK':32},...), ...], key=[...])
@triton.jit
def kernel(..., YBLOCK: tl.constexpr, XBLOCK: tl.constexpr): ...

grid = lambda meta: (cdiv(N, meta['XBLOCK']), cdiv(M, meta['YBLOCK']))  # CORRECT
kernel[grid](args...)  # no XBLOCK/YBLOCK kwargs passed
